package nl.tankarena.content

import java.io.DataInputStream

/**
 * Opaque-pixel masks of the legacy 33×33 pictures, by legacy picture name, for the original's
 * pixel collisions (original/src/check/overlap.c). Generated by `tools-mapconv extract-masks`.
 */
object PictureMasks {
    const val SIZE: Int = LEGACY_TILE_SIZE
    private const val BYTES: Int = (SIZE * SIZE + 7) / 8
    const val RESOURCE_PATH: String = "masks/pictures.mask"

    /** One picture's mask; [isOpaque] is false outside the 33×33 picture. */
    class Mask internal constructor(private val bits: ByteArray) {
        fun isOpaque(x: Int, y: Int): Boolean {
            if (x < 0 || y < 0 || x >= SIZE || y >= SIZE) return false
            val bit = y * SIZE + x
            return (bits[bit ushr 3].toInt() ushr (bit and 7)) and 1 == 1
        }
    }

    private val masks: Map<String, Mask> by lazy { load() }

    fun mask(name: String): Mask? = masks[name]

    fun emptyBits(): ByteArray = ByteArray(BYTES)

    fun setBit(bits: ByteArray, x: Int, y: Int) {
        val bit = y * SIZE + x
        bits[bit ushr 3] = (bits[bit ushr 3].toInt() or (1 shl (bit and 7))).toByte()
    }

    private fun load(): Map<String, Mask> {
        val loader = Thread.currentThread().contextClassLoader ?: PictureMasks::class.java.classLoader
        val stream = loader.getResourceAsStream(RESOURCE_PATH) ?: return emptyMap()
        return DataInputStream(stream.buffered()).use { input ->
            val count = input.readInt()
            buildMap(count) {
                repeat(count) {
                    val name = input.readUTF()
                    val bits = ByteArray(BYTES)
                    input.readFully(bits)
                    put(name, Mask(bits))
                }
            }
        }
    }
}
